package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// LedgerRec 01 LEDGER-REC, 14 bytes
type LedgerRec struct {
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Working-storage
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string
var WsPrevBranch string
var WsPrevAcct string
var WsBal decimal.Decimal
var WsBranchTot decimal.Decimal
var WsGrandTot decimal.Decimal
var WsSkipped int64
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerRec LedgerRec
var ledgerFile *os.File
var scanner *bufio.Scanner
var inputDone bool

func padRight(s string, n int) string {
	if len(s) >= n {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func truncDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	capDigits := int64(intDigits) + int64(scale)
	// divisor = 10^capDigits
	divisor := decimal.New(1, int32(capDigits))
	shifted := d.Shift(scale) // d * 10^scale
	if shifted.IsZero() {
		return decimal.Zero
	}
	neg := shifted.IsNegative()
	absShifted := shifted.Abs()
	if absShifted.Cmp(divisor) >= 0 {
		absShifted = absShifted.Mod(divisor)
		if neg {
			shifted = absShifted.Neg()
		} else {
			shifted = absShifted
		}
	}
	return shifted.Shift(-scale)
}

func formatEdit(v decimal.Decimal, picture string) string {
	// picture like "ZZ,ZZ9.99", "-Z,ZZZ,ZZ9.99", "-ZZZ,ZZZ,ZZ9.99"
	hasSign := false
	if len(picture) > 0 && picture[0] == '-' {
		hasSign = true
	}
	// split picture into integer and decimal parts
	dotIdxPic := strings.Index(picture, ".")
	var intPic string
	var decPic string
	if dotIdxPic >= 0 {
		intPic = picture[:dotIdxPic]
		decPic = picture[dotIdxPic+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	// sign occupies first char if hasSign, not part of intPic digits
	if hasSign {
		// remove leading '-' from intPic
		intPic = intPic[1:]
	}
	// count digit positions in intPic (Z or 9)
	intDigitCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitCount++
		}
	}
	decDigitCount := 0
	for _, c := range decPic {
		if c == 'Z' || c == '9' {
			decDigitCount++
		}
	}

	// sign char
	signChar := ' '
	if hasSign {
		if v.IsNegative() && !v.IsZero() {
			signChar = '-'
		} else {
			signChar = ' '
		}
	}

	absV := v.Abs()
	// ensure scale to decDigitCount for fractional extraction, using Truncate to avoid rounding
	// We need fractional digits exactly.
	// Get string fixed with decDigitCount
	fixed := absV.StringFixed(int32(decDigitCount)) // e.g. "1234.56"
	dotIdxVal := strings.Index(fixed, ".")
	var intStr string
	var fracStr string
	if dotIdxVal >= 0 {
		intStr = fixed[:dotIdxVal]
		fracStr = fixed[dotIdxVal+1:]
	} else {
		intStr = fixed
		fracStr = ""
	}
	// pad/truncate intStr to intDigitCount low-order digits
	if len(intStr) > intDigitCount {
		intStr = intStr[len(intStr)-intDigitCount:]
	} else if len(intStr) < intDigitCount {
		intStr = strings.Repeat("0", intDigitCount-len(intStr)) + intStr
	}
	// ensure fracStr length == decDigitCount
	if len(fracStr) < decDigitCount {
		fracStr = fracStr + strings.Repeat("0", decDigitCount-len(fracStr))
	} else if len(fracStr) > decDigitCount {
		fracStr = fracStr[:decDigitCount]
	}

	// Build output buffer same length as picture
	picRunes := []rune(picture)
	out := make([]rune, len(picRunes))
	// digit index pointer for int part
	digitIdx := 0
	// For suppression: iterate digit positions in intPic left->right
	suppress := true

	// We need quick mapping: for each position in picture, if it's Z/9, consume next int digit
	// For comma suppression: comma becomes space while suppress==true
	// To know suppress state when we encounter comma, suppress reflects whether all previous Z digits were suppressed and no non-zero yet.
	// 9 digit ends suppression.
	for i, ch := range picRunes {
		switch ch {
		case '-':
			out[i] = signChar
		case 'Z', '9':
			d := rune(intStr[digitIdx])
			digitIdx++
			if ch == 'Z' {
				if suppress && d == '0' {
					out[i] = ' '
				} else {
					out[i] = d
					suppress = false
				}
			} else { // '9'
				out[i] = d
				suppress = false
			}
		case ',':
			if suppress {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		case '.':
			out[i] = '.'
			// decimal part suppression ends, no suppression after dot
			suppress = false
		default:
			out[i] = ch
		}
	}
	// Now we have filled integer digits, but we still need to place fractional digits.
	// In our loop above, fractional digit positions are also '9's after the dot.
	// At that point digitIdx would have exhausted int digits; we incorrectly reused intStr for fractional.
	// So we need separate handling: fractional digits should come from fracStr, not intStr.
	// We already consumed intDigits for integer part, but fractional positions also use Z/9.
	// Fix: redo with two pointers.

	// Rebuild correctly with two pointers
	digitIdx = 0
	fracIdx := 0
	suppress = true
	for i, ch := range picRunes {
		switch ch {
		case '-':
			out[i] = signChar
		case 'Z', '9':
			// determine if this position is before or after dot
			if i < dotIdxPic || dotIdxPic == -1 {
				d := rune(intStr[digitIdx])
				digitIdx++
				if ch == 'Z' {
					if suppress && d == '0' {
						out[i] = ' '
					} else {
						out[i] = d
						suppress = false
					}
				} else {
					out[i] = d
					suppress = false
				}
			} else {
				// after dot
				d := rune(fracStr[fracIdx])
				fracIdx++
				out[i] = d
			}
		case ',':
			if suppress {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		case '.':
			out[i] = '.'
			suppress = false
		}
	}
	return string(out)
}

func displayLine(s string) {
	// DISPLAY concatenates and adds newline
	// Use WriteString to preserve spaces
	os.Stdout.WriteString(s + "\n")
}

// Paragraphs

func READ_PARA() {
	if scanner.Scan() {
		line := scanner.Text()
		// scanner strips newline but keeps other spaces? Ensure we handle possible \r
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		rec := padRight(line, 14)
		ledgerRec.BrBranch = rec[0:2]
		ledgerRec.BrAcct = rec[2:6]
		ledgerRec.BrType = rec[6:7]
		amtField := rec[7:14]
		amtField = strings.TrimSpace(amtField)
		if amtField == "" {
			ledgerRec.BrAmt = decimal.Zero
		} else {
			// amtField should be digits, possibly with spaces; strip spaces
			// If contains non-digit, treat missing as 0? but assume digits
			clean := ""
			for _, c := range amtField {
				if c >= '0' && c <= '9' {
					clean += string(c)
				}
			}
			if clean == "" {
				ledgerRec.BrAmt = decimal.Zero
			} else {
				// parse as integer
				// clean may be large, use decimal
				// Use NewFromString then shift?
				// Use decimal.New parsing: value = integer * 10^-2
				// To avoid overflow of int64, parse with decimal
				intVal, _ := decimal.NewFromString(clean)
				ledgerRec.BrAmt = intVal.Shift(-2)
			}
		}
		inputDone = false
		WsEofFlag = "N"
	} else {
		// check error
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		inputDone = true
		WsEofFlag = "Y"
	}
}

func ACCT_BREAK_PARA() {
	WsBalEd = formatEdit(WsBal, "-Z,ZZZ,ZZ9.99")
	displayLine("  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd)
	WsBranchTot = truncDecimal(WsBranchTot.Add(WsBal), 9, 2)
	WsBal = decimal.Zero
}

func BRANCH_BREAK_PARA() {
	WsTotEd = formatEdit(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
	displayLine(" BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd)
	WsGrandTot = truncDecimal(WsGrandTot.Add(WsBranchTot), 9, 2)
	WsBranchTot = decimal.Zero
}

func POST_PARA() {
	WsAmtEd = formatEdit(ledgerRec.BrAmt, "ZZ,ZZ9.99")
	switch ledgerRec.BrType {
	case "D":
		WsBal = truncDecimal(WsBal.Add(ledgerRec.BrAmt), 7, 2)
		displayLine(ledgerRec.BrAcct + " D " + WsAmtEd)
	case "C":
		WsBal = truncDecimal(WsBal.Sub(ledgerRec.BrAmt), 7, 2)
		displayLine(ledgerRec.BrAcct + " C " + WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		displayLine(ledgerRec.BrAcct + " ? SKIPPED")
	}
}

func PROCESS_PARA() {
	if WsFirstFlag == "Y" {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			ACCT_BREAK_PARA()
			BRANCH_BREAK_PARA()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				ACCT_BREAK_PARA()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	POST_PARA()
	READ_PARA()
}

func GRAND_PARA() {
	WsTotEd = formatEdit(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
	displayLine("GRAND TOTAL:" + WsTotEd)
	// WsSkipped display as PIC 99 zero-padded 2 digits (low-order)
	skippedDisp := WsSkipped % 100
	if skippedDisp < 0 {
		skippedDisp += 100
	}
	skippedStr := fmt.Sprintf("%02d", skippedDisp)
	displayLine("SKIPPED: " + skippedStr)
}

func MAIN_PARA() {
	// OPEN INPUT LEDGER-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty? COBOL would error. Exit.
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	ledgerFile = f
	defer f.Close()
	scanner = bufio.NewScanner(ledgerFile)
	// Increase buffer to handle long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)

	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	if WsFirstFlag != "Y" {
		ACCT_BREAK_PARA()
		BRANCH_BREAK_PARA()
	}
	// CLOSE LEDGER-FILE handled by defer
	GRAND_PARA()
}

func main() {
	// init working-storage defaults
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = "  "
	WsPrevAcct = "    "
	WsBal = decimal.Zero
	WsBranchTot = decimal.Zero
	WsGrandTot = decimal.Zero
	WsSkipped = 0

	MAIN_PARA()
}

